<?php $d = json_decode(file_get_contents("routes_data.json"), true); foreach($d as $r) { $uri = $r["uri"]; $mw = implode(",", (array)$r["middleware"]); if(str_contains($uri, "api/") && !str_contains($mw, "auth") && !str_contains($mw, "sanctum") && !str_contains($mw, "api") && !str_contains($uri, "webhook")) echo "Unprotected API: $uri\n"; }
